//   10 = SELECT (pred_i ? A_i : B_i)
// bsg_defines.sv is inlined at the start of this bundle.
`timescale 1ns/1ps

module rta_alu #(
    parameter int width_p      = 8
   ,parameter int prog_width_p = 4
) (
    input  logic [width_p-1:0]      A_i
   ,input  logic [width_p-1:0]      B_i
   ,input  logic                    pred_i

   ,input  logic [prog_width_p-1:0] prog_data_i
   ,input  logic                    prog_done_i

   ,output logic [width_p-1:0]      out_o
   ,output logic                    nz_o
);

  localparam int lg_width_lp     = $clog2(width_p);
  localparam int alu_op_width_lp = 4;

  localparam logic [alu_op_width_lp-1:0] e_alu_add      = 4'd0;
  localparam logic [alu_op_width_lp-1:0] e_alu_sub      = 4'd1;
  localparam logic [alu_op_width_lp-1:0] e_alu_lsl      = 4'd2;
  localparam logic [alu_op_width_lp-1:0] e_alu_lsr      = 4'd3;
  localparam logic [alu_op_width_lp-1:0] e_alu_asr      = 4'd4;
  localparam logic [alu_op_width_lp-1:0] e_alu_mul_lo   = 4'd5;
  localparam logic [alu_op_width_lp-1:0] e_alu_and      = 4'd6;
  localparam logic [alu_op_width_lp-1:0] e_alu_or       = 4'd7;
  localparam logic [alu_op_width_lp-1:0] e_alu_xor      = 4'd8;
  localparam logic [alu_op_width_lp-1:0] e_alu_slt      = 4'd9;
  localparam logic [alu_op_width_lp-1:0] e_alu_select   = 4'd10;

  logic [alu_op_width_lp-1:0] op_li;
  assign op_li = prog_data_i[0 +: alu_op_width_lp];

  logic [width_p-1:0] add_result_lo;
  logic [width_p-1:0] sub_result_lo;
  logic [(2*width_p)-1:0] mul_full_lo;
  logic               slt_result_lo;
  logic [width_p-1:0] mux_result_lo;

  bsg_adder_cin #(.width_p(width_p))
    add_inst (.a_i(A_i)
             ,.b_i(B_i)
             ,.cin_i(1'b0)
             ,.o(add_result_lo)
             );

  bsg_adder_cin #(.width_p(width_p))
    sub_inst (.a_i(A_i)
             ,.b_i(~B_i)
             ,.cin_i(1'b1)
             ,.o(sub_result_lo)
             );

  bsg_mul_synth #(.width_p(width_p))
    mul_inst (.a_i(A_i)
             ,.b_i(B_i)
             ,.o(mul_full_lo)
             );

  assign slt_result_lo = ($signed(A_i) < $signed(B_i));

  always_comb begin
    mux_result_lo = '0;

    unique casez (op_li)
      e_alu_add: begin
        mux_result_lo = add_result_lo;
      end
      e_alu_sub: begin
        mux_result_lo = sub_result_lo;
      end
      e_alu_lsl: begin
        mux_result_lo = A_i << B_i[lg_width_lp-1:0];
      end
      e_alu_lsr: begin
        mux_result_lo = A_i >> B_i[lg_width_lp-1:0];
      end
      e_alu_asr: begin
        mux_result_lo = $unsigned($signed(A_i) >>> B_i[lg_width_lp-1:0]);
      end
      e_alu_mul_lo: begin
        mux_result_lo = mul_full_lo[width_p-1:0];
      end
      e_alu_and: begin
        mux_result_lo = A_i & B_i;
      end
      e_alu_or: begin
        mux_result_lo = A_i | B_i;
      end
      e_alu_xor: begin
        mux_result_lo = A_i ^ B_i;
      end
      e_alu_slt: begin
        mux_result_lo[0] = slt_result_lo;
      end
      e_alu_select: begin
        mux_result_lo = pred_i ? A_i : B_i;
      end
      default: begin
        mux_result_lo = '0;
      end
    endcase
  end

  assign out_o = prog_done_i ? mux_result_lo : '0;
  assign nz_o  = prog_done_i ? (|mux_result_lo) : 1'b0;

