  assign corr_b_li = {width_p{b_i[width_p-1]}} & a_i;

  bsg_adder_cin #(.width_p(width_p))
    corr_add (.a_i(corr_a_li)
             ,.b_i(corr_b_li)
             ,.cin_i(1'b0)
             ,.o(corr_sum_lo)
             );

  logic [prod_width_lp-1:0] corr_aligned_li;
  assign corr_aligned_li = {corr_sum_lo, {width_p{1'b0}}};

