    rta_v4_active_or3 or3_s_active_2 (
        .active_0_i(south_io_c2_prog_active_data0_o),
        .active_1_i(south_io_c2_prog_active_data1_o),
        .active_2_i(south_io_c2_prog_active_pred_o),
        .or_o(or3_s_active_2_or_o)
    );

    rta_v4_active_or3 or3_s_active_3 (
        .active_0_i(south_io_c3_prog_active_data0_o),
        .active_1_i(south_io_c3_prog_active_data1_o),
        .active_2_i(south_io_c3_prog_active_pred_o),
        .or_o(or3_s_active_3_or_o)
    );

    rta_v4_active_pack4 pack_e_active (
        .active_0_i(or3_e_active_0_or_o),
        .active_1_i(or3_e_active_1_or_o),
        .active_2_i(or3_e_active_2_or_o),
        .active_3_i(or3_e_active_3_or_o),
        .active_o(pack_e_active_active_o)
    );

    rta_v4_active_or3 or3_e_active_0 (
        .active_0_i(east_io_r0_prog_active_data0_o),
        .active_1_i(east_io_r0_prog_active_data1_o),
        .active_2_i(east_io_r0_prog_active_pred_o),
        .or_o(or3_e_active_0_or_o)
    );

    rta_v4_active_or3 or3_e_active_1 (
        .active_0_i(east_io_r1_prog_active_data0_o),
        .active_1_i(east_io_r1_prog_active_data1_o),
        .active_2_i(east_io_r1_prog_active_pred_o),
        .or_o(or3_e_active_1_or_o)
    );

    rta_v4_active_or3 or3_e_active_2 (
        .active_0_i(east_io_r2_prog_active_data0_o),
        .active_1_i(east_io_r2_prog_active_data1_o),
        .active_2_i(east_io_r2_prog_active_pred_o),
        .or_o(or3_e_active_2_or_o)
    );

    rta_v4_active_or3 or3_e_active_3 (
        .active_0_i(east_io_r3_prog_active_data0_o),
        .active_1_i(east_io_r3_prog_active_data1_o),
        .active_2_i(east_io_r3_prog_active_pred_o),
        .or_o(or3_e_active_3_or_o)
    );

    simple_buf i_buf_prog_rst_l0 (
        .clk_i(prog_clk_i),
        .data_i(i_buf_prog_rst_l1_data_o),
        .data_o(i_buf_prog_rst_l0_data_o)
    );

    simple_bufr i_buf_prog_done_l0 (
        .clk_i(prog_clk_i),
        .reset_i(i_buf_prog_rst_l0_data_o),
        .data_i(i_buf_prog_done_l1_data_o),
        .data_o(i_buf_prog_done_l0_data_o)
    );

    simple_buf i_buf_prog_rst_l1 (
        .clk_i(prog_clk_i),
        .data_i(prog_rst_i),
        .data_o(i_buf_prog_rst_l1_data_o)
    );

    simple_bufr i_buf_prog_done_l1 (
        .clk_i(prog_clk_i),
        .reset_i(i_buf_prog_rst_l0_data_o),
        .data_i(prog_done_i),
        .data_o(i_buf_prog_done_l1_data_o)
    );

    scanchain_delim i_scanchain_head (
        .prog_we_o(i_scanchain_head_prog_we_o),
        .prog_clk_i(prog_clk_i),
        .prog_rst_i(i_buf_prog_rst_l0_data_o),
        .prog_done_i(i_buf_prog_done_l0_data_o),
        .prog_we_i(prog_we_i),
        .prog_din_i(prog_din_i),
        .prog_dout_o(i_scanchain_head_prog_dout_o)
    );

    scanchain_delim i_scanchain_tail (
        .prog_we_o(i_scanchain_tail_prog_we_o),
        .prog_clk_i(prog_clk_i),
        .prog_rst_i(i_buf_prog_rst_l0_data_o),
        .prog_done_i(i_buf_prog_done_l0_data_o),
        .prog_we_i(south_io_c0_prog_we_o),
        .prog_din_i(south_io_c0_prog_dout_o),
        .prog_dout_o(i_scanchain_tail_prog_dout_o)
    );

    // Output Port Connections
    assign opin_x1y5_0 = east_io_r0_opin_x0y0_0;
    assign opin_x1y5_1 = east_io_r0_opin_x0y0_1;
    assign opin_x1y5_2 = east_io_r0_opin_x0y0_2;
    assign opin_x2y5_0 = east_io_r1_opin_x0y0_0;
    assign opin_x2y5_1 = east_io_r1_opin_x0y0_1;
    assign opin_x2y5_2 = east_io_r1_opin_x0y0_2;
    assign opin_x3y5_0 = east_io_r2_opin_x0y0_0;
    assign opin_x3y5_1 = east_io_r2_opin_x0y0_1;
    assign opin_x3y5_2 = east_io_r2_opin_x0y0_2;
    assign opin_x4y5_0 = east_io_r3_opin_x0y0_0;
    assign opin_x4y5_1 = east_io_r3_opin_x0y0_1;
    assign opin_x4y5_2 = east_io_r3_opin_x0y0_2;
    assign opin_x5y1_0 = south_io_c0_opin_x0y0_0;
    assign opin_x5y1_1 = south_io_c0_opin_x0y0_1;
    assign opin_x5y1_2 = south_io_c0_opin_x0y0_2;
    assign opin_x5y2_0 = south_io_c1_opin_x0y0_0;
    assign opin_x5y2_1 = south_io_c1_opin_x0y0_1;
    assign opin_x5y2_2 = south_io_c1_opin_x0y0_2;
    assign opin_x5y3_0 = south_io_c2_opin_x0y0_0;
    assign opin_x5y3_1 = south_io_c2_opin_x0y0_1;
    assign opin_x5y3_2 = south_io_c2_opin_x0y0_2;
    assign opin_x5y4_0 = south_io_c3_opin_x0y0_0;
    assign opin_x5y4_1 = south_io_c3_opin_x0y0_1;
    assign opin_x5y4_2 = south_io_c3_opin_x0y0_2;
    assign n_input_active_o = pack_n_active_active_o;
    assign w_input_active_o = pack_w_active_active_o;
    assign s_output_active_o = pack_s_active_active_o;
    assign e_output_active_o = pack_e_active_active_o;
    assign prog_dout_o = i_scanchain_tail_prog_dout_o;
    assign prog_we_o = i_scanchain_tail_prog_we_o;
endmodule
